L["关闭 HUD 只隐藏窗口，不会结束追踪。"] = "Closing the HUD only hides the window; tracking continues."
L["关闭副本地图时切换到迷你窗口"] = "Switch to mini map when closing the dungeon map"
L["关闭后重载界面，专业模块整套不再加载"] = "Turning this off and reloading unloads the whole profession module"
L["关闭后：不显示外框，该段落样式与其他行一致。"] = "Off: no outline is drawn; that segment looks like any other row."
L["关闭后：所有段落恢复常规配色，不做灰显处理。"] = "Off: every segment returns to the standard colors, with no dimming."
L["关闭地图增强"] = "Turn off map enhancement"
L["关闭提示框预览"] = "Close tooltip preview"
L["关闭显示固定参考路线；开启比较商人、拍卖行和自制材料。"] = "Off: fixed reference route. On: compare vendors, auctions and crafted materials."
L["关闭过滤"] = "Close filter"
L["关闭这个面板，忽略记录仍然保留"] = "Close this panel; your ignore list is kept"
L["关闭（默认）：只按价格计算路线，不受拍卖行在售数量限制。"] = "Disabled by default: calculate routes using prices without limiting purchases to listed auction quantities."
L["关闭（默认）：只有限量或未核实货源、且拍卖行没有报价的图样不进采购清单，相应配方退回固定参考路线。"] = "Off (default): formulas with only limited/unverified vendor sources and no AH quote are excluded; their recipes fall back to the fixed reference route."
L["关闭（默认）：各类来源的图纸照常参与，价格无法核实的按未知处理、不按 0 金计入。"] = "Off (default): patterns from any source join in; unverified prices stay unknown instead of counting as zero."
L["关闭（默认）：最省钱方案按「材料成本 − 产物拍卖行全价」挑配方，净亏的配方（如精致轻弹丸）不会入选，边做边赚的配方（如劣质炸药）会插在合适位置，每配方最多插 20 次。"] = "Off (default): the cheapest plan picks recipes by material cost minus full auction-house output value; net-losing recipes never join, and profit-making ones (e.g. Coarse Dynamite) get slotted in, capped at 20 crafts per recipe."
L["关闭（默认）：材料按价格规划；不取消图纸的近期在售数量要求。"] = "Off (default): plan materials by price; patterns still require recent auction stock."
L["关闭（默认）：每段独立成行、范围互不重叠；跟练 HUD 始终按拆分状态执行，工具配方能正确插进对应点位。"] = "Off (default): every segment is its own row with no overlap; the follow HUD always runs on the split plan so tool crafts slot in correctly."
L["关闭（默认）：限量或库存未核实的商人图样不参与采购；只有允许拍卖行图纸且报价可用时，才改从拍卖行购买。"] = "Off by default: limited or unverified vendor stock is excluded. Auction purchases require both an eligible quote and permission to buy auction patterns."
L["关闭：不再记录；已开始的记录会归档到「制作记录」的历史里，重新打开可在下次进升级页时恢复。"] = "Off: recording stops; the current run is archived into the craft log history and resumes when you turn it back on."
L["关闭：不额外安排工具准备；工具配方仍可作为普通升级配方参与计算。"] = "Off: do not add tool preparation; tool recipes can still be considered as normal leveling recipes."
L["关闭：保持原样，区间互相跨越的两行上下排列显示；只有工具步骤的拆分不受本项影响。"] = "Off: keep the two spanning rows stacked as-is; only tool-step splitting is unaffected by this option."
L["关闭：允许使用拍卖行图纸报价，仍受来源、价格和库存设置限制。"] = "Off: allow auction pattern quotes, subject to source, price and stock settings."
L["关闭：允许使用未学配方，计入材料与所需图纸采购成本。"] = "Off: allow unlearned recipes, including materials and required formula purchases."
L["关闭：只看采购支出；剩余产物按卖店价折算，路线卡第三行显示净成本。"] = "Off: spend only. Leftover products are valued at vendor price; the third line shows the net cost."
L["关闭：可先查看路线；请打开拍卖行完成一次完整扫描后重新计算费用。"] = "Off: preview the route, then run a full scan at the auction house to recalculate costs."
L["关闭：可查看含缺价材料的方案，但不会把未知费用计为零。"] = "Off: view plans with missing material prices; unknown costs are never treated as zero."
L["关闭：各类来源的图纸照常参与，价格无法核实的按未知处理、不按 0 金计入。"] = "Off: patterns from any source join in; unverified prices stay unknown instead of counting as zero."
L["关闭：含缺价材料的配方直接参与比较，总价按已知价格计算，界面标注为估算下限。"] = "Off: recipes with unpriced materials compete directly; the total is computed from known prices and shown as a lower-bound estimate."
L["关闭：未知来源图纸照常参与计算，图纸费用按未知处理。"] = "Off: patterns of unknown source still count, with their cost treated as unknown."
L["关闭：材料只按价格规划；拍卖行图纸仍需完整扫描后才能参与路线。"] = "Off: plan materials by price only. Auction patterns still require a full scan before entering the route."
L["关闭：查看从零开始的最优路线与总花费。"] = "Off: shows the optimal route and total cost from scratch."
L["其中 %d 种产物售价未知，未计回血"] = "%d product prices unknown and excluded"
