L["开启 = 只算当前技能到 300 的路线；关闭 = 从 1 全量重算整条路线（预估全程花费）"] = "On = route from current skill to 300; off = full recalc from 1 (estimates total cost)"
L["开启后会自动切到自动计算模式"] = "Turning it on switches the mode to automatic"
L["开启后可能选择限量商人，到访时可能无货；非金币拾取绑定来源仍需对应许可。"] = "May select limited-stock NPCs that are sold out when visited; non-gold acquisition of bound patterns still requires permission."
L["开启后计入另一专业所需的材料费用，最高 300；查看未学专业时需先选择搭配主专业。"] = "Include materials to level the other profession up to 300. Choose a partner for an unlearned target profession."
L["开启后：下一个要练的段落四周显示一圈主题绿描边，一眼定位当前制作路线；外框只是描边，不影响行内容与点击。"] = "On: the next segment to train gets a green themed outline so you can spot your current route at a glance. The outline is decorative and does not affect row content or clicks."
L["开启后：同一配方被工具步骤隔开的两段并作一行，范围恢复连续，但看不出工具占用了哪些技能点。"] = "On: two same-recipe segments separated by a tool step show as one continuous row, hiding which skill points the tool occupies."
L["开启后：段名、出处、数量文字变暗，配方与材料图标去饱和，不再作为下一个要关注的制作目标；"] = "On: segment names, sources, and counts dim, and recipe and material icons desaturate, so it no longer reads as the next target to focus on."
L["开启回血时，选方只按平均会做出的冲点成品估算收益。"] = "With sales recovery on, recipe selection credits green leveling output at the average attempt rate."
L["开启（默认）：先用能算出真实成本的配方；只有某段确实没有任何有价配方时，才退回含缺价材料的方案，并在该段标「成本下限」。"] = "On (default): use only recipes with a real cost first; only when a level range has no priced recipe at all does it fall back to recipes with unpriced materials, and that range is marked as a cost lower bound."
L["开启（默认）：如自爆绵羊 154-184 内含青铜框架 158-174 时，绵羊拆成 154-158 与 174-184 两行，制作次数按区间收益比例分摊、总数不变。"] = "On (default): if Explosive Sheep 154-184 contains Bronze Framework 158-174, the sheep splits into 154-158 and 174-184; craft counts are shared by expected gain per range with the total unchanged."
L["开启（默认）：来源价格无法核实的图纸不进路线，对应配方退回其他方案或固定参考路线。"] = "On (default): patterns whose price cannot be verified stay out of the route; those recipes fall back to another option or the fixed reference route."
L["开启（默认）：算出路线后自动开始记录，升级 HUD 与「制作记录」页都靠它。"] = "On (default): recording starts automatically once the route is ready; both the leveling HUD and the craft log depend on it."
L["开启：「最省钱」按净成本挑选配方；其他路线方案保留各自目标，并显示预计回血。"] = "On: Cheapest ranks recipes by net cost; other route schemes retain their own objectives and show expected recovery."
L["开启：「最省钱」计入预计回血，盈利优先每配方最多20次；其他方案保留原目标。"] = "Cheapest includes estimated recovery, with profit prioritized for up to 20 crafts per recipe. Other strategies keep their objectives."
L["开启：产物收益打七折再比较，只留利润更高的机会，适合打算把产物批量上架的情况。"] = "On: output value counts at 70%, keeping only higher-profit openings - for bulk posting outputs on the AH."
L["开启：拍卖行图纸报价不参与采购；限量商人图样还需开启「允许采购限量图样」。"] = "On: exclude auction pattern quotes. Limited vendor stock also requires Allow limited-stock patterns."
L["开启：掉落、任务、通货兑换图纸的配方不参与路线，避免为一张图纸长跑或按 0 金计入。"] = "On: recipes whose patterns drop, come from quests or cost currency stay out of the route, so no long trip per pattern and no zero-gold costing."
L["开启：材料和图纸共用可购数量，数量不足时尝试其他货源或配方。"] = "On: materials and patterns share available stock; try other sources or recipes when supply is insufficient."
L["开启：材料和图纸共用可购数量；数量不足时尝试其他货源或配方，数量未知时提示重新扫描。"] = "Enabled: materials and recipes share the available quantity. Shortages use alternative sources or recipes; unknown quantities prompt a rescan."
L["开启：每种必需工具至少备齐一件；比较购买和制作，购买进入购物清单，制作进入升级路线。"] = "On: prepare at least one of each required tool; compare buying and crafting. Purchases go on the shopping list; crafts go in the leveling route."
L["开启：精确方案按净成本挑选配方；其他方案仍按采购支出选，但会显示预计回血。"] = "On: the precise solver ranks recipes by net cost. Other schemes still rank by spend but show expected recovery."
L["开启：购物清单只列出还缺的材料，已备齐的自动隐藏。"] = "On: only list reagents you still need; fully stocked ones are hidden."
L["开启：路线更可靠，但可能出现无配方可用的缺口区间。"] = "On: more reliable route, but gaps with no usable recipe may appear."
L["开启：路线里的每一段都能立刻开做。"] = "On: every segment of the route can be crafted right away."
L["开启：这类图样计入路线与采购；商人报价仅作参考，到访时可能无货。"] = "On: these formulas enter the route and shopping list; vendor quotes are advisory and stock may be gone on arrival."
L["开启：适合练级中途打开手册直接照着做。"] = "On: best for picking the guide up mid-leveling."
