L["奖励（选取方式未公布）"] = "Rewards (selection method unpublished)"
L["容器：%s"] = "Container: %s"
L["档位 %d"] = "Tier %d"
L["没在名单里出现的朋友，\n你们的反馈和建议同样让本插件变得更好。"] = "To everyone not named here: your feedback and suggestions made this addon better too."

L["塔纳利斯 · 天涯海滩"] = "Tanaris · Land's End"
L["到地图最右下角的天涯海滩，点地上「半埋的机甲」和「暗门」各一次：第一次只给一段描述，第二次才接到任务。"] = "Go to Land's End Beach in the bottom-right corner of the map and click the half-buried mechano-tank and the hidden hatch once each: the first click only gives flavour text, the second hands you the quest."
L["冬泉谷 · 永望镇"] = "Winterspring · Everlook"
L["飞到永望镇，最大那间屋子的台子上找「努米」，交「冷淡之谊」接「红口袋，蓝受心」。"] = "Fly to Everlook and find Numi on the platform of the biggest house: turn in Frosty Friendship and take Red Pouch, Blue Heart."
L["燃烧平原 · 北面偏远营地"] = "Burning Steppes · remote camp up north"
L["从燃烧平原 59,29 沿着山坡往北走，到 53.0,24.8 的偏僻营地，点地上的「大红口袋」交任务。"] = "From 59,29 in the Burning Steppes follow the slope north to the isolated camp at 53.0,24.8 and click the Big Red Pouch on the ground to turn in."
L["燃烧平原 · 营地周围"] = "Burning Steppes · around the camp"
L["在营地周围杀「黑石私运商」和「萨弗隆私运者」，各拾取 5 个「垂直复合补片加装器」和「黄铜配制耐热法兰」。"] = "Kill Blackrock Bootleggers and Sulfuron Smugglers around the camp for 5 Vertical Composite Patch Fittings and 5 Brass Heat-Resistant Flanges."
L["永望镇 → 钻井平台"] = "Everlook -> oil rig"
L["回永望镇把「偷猎者窝点」交给「努米」，接「返程长票」。"] = "Return to Everlook, hand Poacher's Den to Numi and take The Long Way Back."
L["再跑回塔纳利斯南边的钻井平台，把「返程长票」交给「塞巴斯蒂安·尤尔根斯」，接最后一步「朝来隙往」。"] = "Then run back to the rig south of Tanaris, hand The Long Way Back to Sebastian Jurgens and take the last step, Rift Crossing."
L["跟着「塞巴斯蒂安·尤尔根斯」上二楼，点他修好的机器传送：联盟落到西部荒野，部落落到提瑞斯法林地。"] = "Follow Sebastian Jurgens upstairs and click the machine he repaired: Alliance land in Westfall, Horde in Tirisfal Glades."
L["100% → 95%"] = "100% -> 95%"
L["反篡改护盾"] = "Anti-tamper shielding"
L["盾在的时候打不动本体，只打断不输出：每次打断掉 2 层护盾，分好两个打断位轮流上，盾全掉再开打。"] = "The body takes no damage while the shield is up, so interrupt and nothing else: every interrupt strips 2 layers, so assign two interrupters to alternate. Start dps once it is gone."
L["95% → 75%"] = "95% -> 75%"
L["巨型防护性铁纹 ×4"] = "Giant defensive runes ×4"
L["护甲和减伤拉满，坦克风筝、其他人跟上减速（断筋 / 寒冰箭 / 震荡射击），4 层掉完再站定输出。"] = "Armour and damage reduction are maxed out: the tank kites while everyone else keeps slows up (Hamstring / Frostbolt / Concussive Shot). Stand and dps once all 4 stacks fall off."
L["75% → 60%"] = "75% -> 60%"
L["收割庄稼"] = "Harvest"
L["群体旋风斩，读条时近战和坦克先跑开，远程在外面打；读完再贴回去。"] = "A whirlwind: melee and the tank step out on the cast while ranged keep firing; close back in when it ends."
L["60% → 25%"] = "60% -> 25%"
L["抓钩与额外伤害"] = "Grapple and extra damage"
L["对当前坦克有一下约 2000 的抓钩伤害，轮流缴械，挫志照旧卡着最后一秒补。"] = "A grapple hit of roughly 2000 on the current tank: rotate disarms and keep re-applying Demoralizing Shout on the last second."
L["25% → 0%"] = "25% -> 0%"
L["狂暴 · 法术易伤"] = "Enrage · spell vulnerability"
L["挫志的额外减攻强失效，改由法系开爆发；物理伤害和斩杀压不动，坦克开盾墙硬扛到最后。"] = "The extra attack-power cut from Demoralizing Shout stops working, so casters pop their cooldowns instead. Physical damage and Execute barely move it; the tank uses Shield Wall and holds on."
L["「大红口袋」说明写着「使你的有效潜行等级提高 2」，实际装备后是降低 2 级潜行——翻译错了，盗贼和野德别背。"] = "The Big Red Pouch says it raises your effective stealth level by 2, but wearing it actually lowers stealth by 2 — a bad translation. Rogues and feral druids should leave it in the bank."
L["BOSS 只能 5 人队，开团打不了；也不能拉进暴风城或幽暗城。"] = "The boss only allows a 5-man party (a raid cannot do it) and it cannot be dragged into Stormwind or Undercity."
L["前四步 55 级可接，后三步要 58 级；联盟部落都能做，全程没有阵营限制，难点只在跑路与游泳。"] = "The first four steps open at 55 and the last three need 58; both factions can do it with no faction restriction — the only real work is travel and swimming."
L["这条链给什么"] = "What the chain gives"
L["探索赛季遗留 · 塔纳利斯隐藏任务链"] = "Season of Discovery leftover · a hidden chain in Tanaris"
L["塔纳利斯最南端的天涯海滩上躺着一台坠毁机甲。修好它、给冬泉谷的老同事跑一趟腿、再从燃烧平原的偷猎者营地把零件抢回来，最后在西部荒野或提瑞斯法林地唤出一台麦田傀儡。全程没有阵营限制，55 级就能接，真正费时间的是跑图和游泳。"] = "A crashed mechano-tank lies on Land's End Beach at the southern tip of Tanaris. Repair it, run an errand for an old colleague in Winterspring, fight the parts back from a poacher camp in the Burning Steppes, and at the end summon a harvest golem in Westfall or Tirisfal Glades. No faction restriction, the chain opens at 55, and the real time sink is travel and swimming."
L["④ 拾取"] = "Step 4 pickup"
L["布甲头部"] = "Cloth head"
L["交⑦拾取"] = "Step 7 pickup"
L["大红口袋：16 格容器，在④的营地里点地上的红口袋就归你，只要背包的人到这一步就可以收工。说明里的「潜行等级提高 2」是错的，见最后一栏。"] = "Big Red Pouch: a 16-slot container. Clicking the pouch on the ground in step 4 is what puts it in your bags, so bag hunters can stop right there. Its 'stealth +2' line is wrong — see the last section."
L["太阳眼镜：布甲头部，装等 100、101 护甲，唯一的看点是外观，戴上去很出片。"] = "Sun Glasses: cloth head, item level 100, 101 armour. The only reason to take them is the look — they photograph very well."
L["预感与战斗远见：交⑦时在「机械臂」旁拾取的那件东西，原本是教战士符文的道具，现在只能当玩具看，而且有拾取后不进背包的毛病。"] = "Premonition and Battle Foresight: picked up next to the Mechanical Arm when you turn in step 7. It used to teach warriors a rune, now it is just a toy — and it sometimes fails to land in your bags."
L["七步跑完"] = "Seven steps"
L["起点塔纳利斯 · 终点西部荒野 / 提瑞斯法林地"] = "Starts in Tanaris · ends in Westfall / Tirisfal Glades"
L["麦田傀儡 V000-A"] = "Harvest Golem V000-A"
L["本服约 20 万血 · 5 个阶段 · 最多 5 人"] = "About 200k HP here · 5 phases · 5 players max"
L["队伍至少 1 坦 1 奶，剩下的位置带法系。坦克穿输出装拿盾就能扛，25% 之后有法术易伤，带个法系会快很多。"] = "Bring at least one tank and one healer and fill the rest with casters. A tank in dps gear with a shield holds fine, and the spell vulnerability below 25% makes casters pay off."
L["整场只有两件事不能断：挫志和雷霆。挫志会给他叠一个不能刷新的减攻强 debuff，必须等它跳完的瞬间补上，不然容易直接倒 T。"] = "Only two things must never drop: Demoralizing Shout and Thunder Clap. Shout puts a non-refreshing attack-power debuff on him, so re-apply it the instant it expires or the tank drops."
L["跑图与踩坑"] = "Travel and pitfalls"
L["先看这几条再出发"] = "Read these before you set off"
L["太阳眼镜"] = "Sun Glasses"

L["迷滩机器人"] = "Land's End Mecha"
L["塔纳利斯"] = "Tanaris"
