L["返程长票"] = "The Long Way Back"
L["再跑回塔纳利斯南边的钻井平台，把「返程长票」交给「塞巴斯蒂安·尤尔根斯」。"] = "Then run back to the rig south of Tanaris and hand The Long Way Back to Sebastian Jurgens."
L["朝来隙往"] = "Rift Crossing"
L["西部荒野 / 提瑞斯法林地"] = "Westfall / Tirisfal Glades"
L["交任务拾取"] = "picked up on turn-in"
L["占武器栏"] = "uses weapon slot"
L["打断掉盾"] = "interrupts drop the shield"
L["两名打断位"] = "two interrupters"
L["盾在的时候打不动本体，只打断不输出：每次打断掉 2 层护盾，盾全掉再开打。"] = "While the shield is up the body takes no damage: interrupt only, do not dps. Each interrupt removes 2 shield stacks; burn him once they are gone."
L["分好两个打断位轮流上，谁空谁补，盾一掉立刻转火本体。"] = "Assign two interrupters to alternate, whoever is free fills in, and switch to the body the moment the shield drops."
L["护甲减伤拉满"] = "armour and DR maxed"
L["坦克 + 减速位"] = "tank + snarer"
L["护甲和减伤拉满，正面打不动，要一边跑一边掉层。"] = "Armour and damage reduction are maxed; you cannot burn him head-on, the stacks have to fall off while you move."
L["坦克风筝、其他人跟上减速（断筋 / 寒冰箭 / 震荡射击），4 层掉完再站定输出。"] = "The tank kites while everyone else keeps a snare up (Hamstring / Frostbolt / Concussive Shot); stand and dps once all 4 stacks are gone."
L["群体旋风斩"] = "AoE whirlwind"
L["近战 + 坦克"] = "melee + tank"
L["群体旋风斩，读条时近战和坦克要撤出近身范围。"] = "AoE whirlwind - melee and the tank have to leave melee range while it casts."
L["读条一开始就侧移出 8 码，远程在外面继续打；读完再贴回去。"] = "Strafe about 8 yards out as soon as the cast starts, keep dpsing from range, and close back in when it ends."
L["对坦克约 2000"] = "~2000 on the tank"
L["对当前坦克有一下约 2000 的抓钩伤害，挫志照旧卡着最后一秒补。"] = "A hook hits the current tank for about 2000; keep refreshing Demoralizing Shout on the last second as usual."
L["轮流缴械降伤害，治疗盯住坦克血线，别在抓钩前后断奶。"] = "Rotate disarms to cut the damage, and healers keep the tank topped - do not let heals lapse around the hook."
L["物理抗性高"] = "high physical resistance"
L["法系"] = "casters"
L["狂暴之后物理伤害和斩杀压不动，反而吃法术易伤。"] = "Once enraged, physical damage and Execute barely move him, but he takes extra spell damage."
L["法系开爆发收尾，坦克开盾墙硬扛，别再指望物理职业拉平。"] = "Casters pop cooldowns to finish, the tank holds with Shield Wall, and stop expecting physical dps to carry."
L["塔纳利斯最南端的天涯海滩上躺着一台坠毁机甲。修好它、给冬泉谷的老同事跑一趟腿、再从燃烧平原的偷猎者营地把零件抢回来，最后在西部荒野或提瑞斯法林地唤出一台麦田傀儡。全程没有阵营限制，真正费时间的是跑图和游泳。"] = "A crashed mechano-tank lies on Land's End Beach at the southern tip of Tanaris. Repair it, run an errand for an old colleague in Winterspring, fight the parts back from a poacher camp in the Burning Steppes, and finally summon a harvest golem in Westfall or Tirisfal Glades. No faction restriction - the real time sink is travel and swimming."
