L["×1 · 可用 3 次"] = "x1 · 3 uses"
L["当场交掉接下一环，同时拿到 1 瓶「制导浮力加速器」，可使用 3 次，加快游速，后面游泳全靠它，不然会疲劳。"] = "Turn it in on the spot to take the next step; you receive 1 Guided Buoyancy Accelerator with 3 uses. It speeds up swimming and the whole crossing depends on it - without it you will tire out."
L["朝正南方的海岛（灯塔方向）游过去，记住游直线不要停，记住喝刚才的药水，岛边就是钻井平台，上平台顶层，找「塞巴斯蒂安·尤尔根斯」交任务。"] = "Swim due south toward the island (head for the lighthouse). Go in a straight line, do not stop, and remember to drink the potion you just got. The rig sits at the island's edge - climb to the top floor and turn in to Sebastian Jurgens."
L["接完就直奔燃烧平原。"] = "Take it and head straight for the Burning Steppes."
L["交完直接拿到「大红口袋」：16 格容器，只要背包的话，做到这一步就可以收工了。"] = "Turn it in and you get the Big Red Pouch right away: a 16-slot container. If bags are all you want, you can stop here."
L["用任务物品召唤「麦田傀儡 V000-A」，打完在旁边的「机械臂」处交任务，拿「太阳眼镜」和「预感与战斗远见」。"] = "Use the quest item to summon Harvest Golem V000-A; after the kill, turn in at the Mechanical Arm beside it for the Sun Glasses and Premonition and Battle Foresight."

L["① 1 瓶 · 3 次"] = "1 - 1 potion, 3 uses"

L["注意事项"] = "Notes"
L["海上钻井平台"] = "the offshore drilling platform"
L["药水 1 瓶、能用 3 次：游泳前确认身上有 buff，游直线。"] = "1 potion with 3 uses: make sure the buff is up before you swim, and swim in a straight line."
L["「大红口袋」写着「潜行等级提高 2」，实际是降低 2 级，翻译错了，潜行职业谨慎使用。"] = "The \"Big Red Pouch\" claims it raises your stealth level by 2, but it actually lowers it by 2 - a translation error. Stealth classes should use it with care."
L["BOSS 大约 30 分钟重置，团灭不回血可以接着打。"] = "The boss resets in about 30 minutes; he does not heal after a wipe, so you can keep pulling."
L["前四步 55 级可接，后三步要 58 级，两阵营都能做"] = "The first four steps open at 55, the last three need 58, and both factions can do the chain"
