L["四条材料线"] = "Four goods lines"
L["围栏边带金边的小铁箱就是控制台，点一下召唤遥控坦克，四个技能出现在动作条上方，跟别人的坦克对轰。100 血 100 蓝，五分钟一场。"] = "The small gold-trimmed iron box by the fence is the console: click it to summon a remote tonk with four abilities above your action bar and battle other tonks. 100 HP, 100 mana, five minutes per match."
