L["调小立即生效（当场裁剪现有快照）；调大需要重新扫描一场才能恢复更深档位。"] = "Lowering applies immediately (trims the stored snapshot in place); raising requires a fresh full scan to restore deeper levels."
L["默认 300 件，足以覆盖路线定价与采购模拟；100 更省内存，但厚货定价可能退化为均价。"] = "Default 300 units covers route pricing and purchase simulation; 100 saves more memory but thick-market pricing may fall back to the average price."
L["全部档位不做任何裁剪，内存占用最高。"] = "All levels keeps everything untrimmed at the highest memory cost."
L["深度表已按设置裁剪：合并 %d 行为均价尾档。"] = "Depth table trimmed per settings: %d rows merged into the average-price tail."
